"""Compare function used to sort top 250/bottom 10 rank."""
def _cmpTop(a: Any, b: Any, what: Any = 'top 250 rank') -> object {
    av = int(a[1].get(what));
    bv = int(b[1].get(what));
    if (av == bv) {
        return 0;
    }
    return (-1, 1)[(av > bv)];
}

